const first = $input.first()?.json;
const batch = Array.isArray(first) ? first[0] : first;

if (!batch || !batch.id) {
  return [{ json: { has_batch: false, action: 'no_started_batch', message: 'No competitor batch with status=started.' } }];
}

return [{
  json: {
    has_batch: true,
    batch_id: batch.id,
    target_video_count: batch.target_video_count || 50,
    platform: batch.platform || 'instagram'
  }
}];

const accountsRaw = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]).filter(Boolean);
const batch = $('Code: normalize batch').item.json;
const accounts = accountsRaw.filter(a => a.account_url);

if (accounts.length === 0) {
  return [{
    json: {
      has_accounts: false,
      batch_id: batch.batch_id,
      message: 'No active Instagram competitor accounts in competitor_accounts.'
    }
  }];
}

const perAccountLimit = Math.max(12, Math.ceil((batch.target_video_count || 50) / accounts.length) + 5);
return [{
  json: {
    has_accounts: true,
    batch_id: batch.batch_id,
    target_video_count: batch.target_video_count || 50,
    accounts,
    apify_input: {
      directUrls: accounts.map(a => a.account_url),
      resultsType: 'posts',
      resultsLimit: perAccountLimit,
      addParentData: false
    }
  }
}];

const batch = $('Code: build Apify input').item.json;
const accounts = batch.accounts || [];
const accountByUsername = new Map();
const accountByUrl = new Map();
for (const a of accounts) {
  if (a.username) accountByUsername.set(String(a.username).toLowerCase(), a);
  if (a.account_url) accountByUrl.set(String(a.account_url).replace(/\/$/, '').toLowerCase(), a);
}

const raw = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]).filter(Boolean);
const target = batch.target_video_count || 50;

function num(v) {
  const n = Number(v || 0);
  return Number.isFinite(n) ? n : 0;
}
function cleanUrl(v) {
  return String(v || '').replace(/\/$/, '');
}
function videoUrl(p) {
  return p.url || p.videoUrl || p.video_url || (p.shortCode ? `https://www.instagram.com/reel/${p.shortCode}/` : '');
}
function ownerUsername(p) {
  return String(p.ownerUsername || p.username || p.owner?.username || '').toLowerCase();
}

let videos = raw.map(p => {
  const username = ownerUsername(p);
  const account = accountByUsername.get(username) || accountByUrl.get(cleanUrl(p.ownerProfileUrl || p.ownerUrl).toLowerCase()) || null;
  const views = num(p.videoViewCount || p.videoPlayCount || p.views || p.viewCount);
  const likes = num(p.likesCount || p.likes || p.likeCount);
  const comments = num(p.commentsCount || p.comments || p.commentCount);
  const saves = num(p.saves || p.savesCount);
  const shares = num(p.shares || p.sharesCount);
  const followers = num(p.followersCount || p.ownerFollowersCount || p.owner?.followersCount);
  const isVideo = Boolean(p.videoUrl || p.video_url || views > 0 || String(p.type || '').toLowerCase().includes('video'));
  return {
    raw: p,
    account,
    platform: 'instagram',
    video_url: videoUrl(p),
    shortcode: p.shortCode || p.shortcode || p.id || null,
    caption: String(p.caption || p.text || '').slice(0, 2000),
    published_at: p.timestamp || p.takenAtTimestamp ? new Date((p.takenAtTimestamp || 0) * 1000).toISOString() : (p.date || null),
    thumbnail_url: p.displayUrl || p.thumbnailUrl || p.imageUrl || '',
    raw_video_storage_path: null,
    views,
    likes,
    comments,
    saves,
    shares,
    followers_at_scan: followers || null,
    isVideo
  };
}).filter(v => v.isVideo && v.video_url).slice(0, Math.max(target * 2, 80));

const byAccount = new Map();
for (const v of videos) {
  const key = v.account?.id || ownerUsername(v.raw) || 'unknown';
  if (!byAccount.has(key)) byAccount.set(key, []);
  byAccount.get(key).push(v);
}

for (const group of byAccount.values()) {
  const viewValues = group.map(v => v.views).filter(v => v > 0).sort((a, b) => a - b);
  const avg = viewValues.length ? viewValues.reduce((a, b) => a + b, 0) / viewValues.length : 0;
  group.sort((a, b) => b.views - a.views);
  const topCount = Math.max(1, Math.ceil(group.length * 0.2));
  group.forEach((v, idx) => {
    const engagement = v.views > 0 ? (v.likes + v.comments * 3 + v.saves * 5 + v.shares * 6) / v.views : 0;
    const multiplier = avg > 0 ? v.views / avg : 0;
    const top20 = idx < topCount;
    const strongEngagement = engagement >= 0.08 && v.views > 0;
    const strict = top20 || multiplier >= 2 || strongEngagement;
    const extreme = multiplier >= 20;
    const score = (multiplier * 45) + (engagement * 400) + (top20 ? 20 : 0) + (extreme ? 80 : 0) + Math.log10(Math.max(v.views, 1));
    Object.assign(v, {
      account_average_views: avg || null,
      views_multiplier: multiplier || null,
      engagement_rate: engagement || null,
      selection_score: score,
      _strict: strict,
      _extreme: extreme,
      _reason: extreme ? 'extreme_viral_20x' : strict ? [top20 && 'top_20_percent', multiplier >= 2 && 'views_2x_account_avg', strongEngagement && 'strong_engagement'].filter(Boolean).join(',') : 'below_strict_threshold'
    });
  });
}

videos.sort((a, b) => b.selection_score - a.selection_score);
const strictVideos = videos.filter(v => v._strict || v._extreme);
const selected = new Set(strictVideos.map(v => v.video_url));
for (const v of videos) {
  if (selected.size >= 10) break;
  selected.add(v.video_url);
}

const limited = videos.slice(0, Math.max(target, selected.size));
const rows = limited.map(v => {
  const isSelected = selected.has(v.video_url);
  const near = isSelected && !v._strict && !v._extreme;
  return {
    batch_id: batch.batch_id,
    competitor_account_id: v.account?.id || null,
    platform: v.platform,
    video_url: v.video_url,
    shortcode: v.shortcode,
    caption: v.caption,
    published_at: v.published_at,
    thumbnail_url: v.thumbnail_url,
    raw_video_storage_path: null,
    views: v.views || null,
    likes: v.likes || null,
    comments: v.comments || null,
    saves: v.saves || null,
    shares: v.shares || null,
    followers_at_scan: v.followers_at_scan,
    account_average_views: v.account_average_views,
    views_multiplier: v.views_multiplier,
    engagement_rate: v.engagement_rate,
    selection_score: v.selection_score,
    selection_reason: near ? 'near_threshold_fill_to_minimum_10' : v._reason,
    selection_type: v._extreme ? 'extreme_viral' : v._strict ? 'strict' : near ? 'near_threshold' : 'rejected',
    status: isSelected ? (near ? 'near_threshold' : 'qualified') : 'rejected'
  };
});

const finalSelected = rows.filter(r => ['strict', 'near_threshold', 'extreme_viral'].includes(r.selection_type));
const strictCount = rows.filter(r => r.selection_type === 'strict' || r.selection_type === 'extreme_viral').length;
const nearCount = rows.filter(r => r.selection_type === 'near_threshold').length;

return [{
  json: {
    batch_id: batch.batch_id,
    found_video_count: rows.length,
    strict_selected_count: strictCount,
    near_threshold_selected_count: nearCount,
    final_selected_count: finalSelected.length,
    rows,
    selection_notes: `WF01 processed ${raw.length} raw items, saved ${rows.length} videos, selected ${finalSelected.length}: strict/extreme=${strictCount}, near-threshold=${nearCount}.`
  }
}];
